const retentionTenants = `-- name: RetentionTenants :many
SELECT t::uuid AS tenant_id FROM app_retention_tenants($1, $2, $3::uuid, $4) AS t
`

type RetentionTenantsParams struct {
	Kind        string
	Cutoff      time.Time
	AfterTenant *uuid.UUID
	MaxTenants  int32
}

// Tenants com dados do tipo informado vencidos no corte (somente IDs).
func (q *Queries) RetentionTenants(ctx context.Context, arg RetentionTenantsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, retentionTenants,
		arg.Kind,
		arg.Cutoff,
		arg.AfterTenant,
		arg.MaxTenants,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var tenant_id uuid.UUID
		if err := rows.Scan(&tenant_id); err != nil {
			return nil, err
		}
		items = append(items, tenant_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const takeOverIdempotencyKey = `-- name: TakeOverIdempotencyKey :execrows
UPDATE idempotency_keys SET locked_until = $1, lease_token = $2::uuid
 WHERE tenant_id = $3 AND client_id = $4 AND operation = $5 AND idempotency_key = $6
   AND status = 'in_progress' AND locked_until < $7
`

type TakeOverIdempotencyKeyParams struct {
	LockedUntil    *time.Time
	LeaseToken     uuid.UUID
	TenantID       uuid.UUID
	ClientID       string
	Operation      string
	IdempotencyKey string
	Now            *time.Time
}

// Recuperação de processamento interrompido: assume a chave apenas se o
// lease anterior expirou (um único processo vence a disputa). O token novo
// passa a ser o único aceito para registrar o resultado ou liberar a chave.
func (q *Queries) TakeOverIdempotencyKey(ctx context.Context, arg TakeOverIdempotencyKeyParams) (int64, error) {
	result, err := q.db.Exec(ctx, takeOverIdempotencyKey,
		arg.LockedUntil,
		arg.LeaseToken,
		arg.TenantID,
		arg.ClientID,
		arg.Operation,
		arg.IdempotencyKey,
		arg.Now,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const upsertUserFromClaims = `-- name: UpsertUserFromClaims :one

INSERT INTO users (id, oidc_issuer, oidc_subject, email, display_name, status, created_at, updated_at, last_login_at)
VALUES ($1, $2, $3, $4, $5, 'active', $6, $6, $6)
ON CONFLICT (oidc_issuer, oidc_subject) DO UPDATE
   SET email = EXCLUDED.email, display_name = EXCLUDED.display_name, last_login_at = EXCLUDED.last_login_at
RETURNING id, oidc_issuer, oidc_subject, email, display_name, status, created_at, updated_at, last_login_at
`

type UpsertUserFromClaimsParams struct {
	ID          uuid.UUID
	OidcIssuer  string
	OidcSubject string
	Email       string
	DisplayName string
	Now         time.Time
}

// Usuários, outbox, inbox, auditoria, idempotência, agendamentos e dead letters.
func (q *Queries) UpsertUserFromClaims(ctx context.Context, arg UpsertUserFromClaimsParams) (User, error) {
	row := q.db.QueryRow(ctx, upsertUserFromClaims,
		arg.ID,
		arg.OidcIssuer,
		arg.OidcSubject,
		arg.Email,
		arg.DisplayName,
		arg.Now,
	)
	var i User
	err := row.Scan(
		&i.ID,
		&i.OidcIssuer,
		&i.OidcSubject,
		&i.Email,
		&i.DisplayName,
		&i.Status,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.LastLoginAt,
	)
	return i, err
}
